import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

class HttpError extends Error {
  constructor(status, code, message) {
    super(message || code);
    this.status = status;
    this.code = code;
  }
}
const bad = (m) => new HttpError(400, 'validation', m || 'Invalid request');
const notFound = (m) => new HttpError(404, 'not_found', m || 'Not found');
const forbidden = (m) => new HttpError(403, 'forbidden', m || 'Forbidden');
const conflict = (m, code = 'conflict') => new HttpError(409, code, m || 'Conflict');

const ROLE_RANK = { viewer: 1, editor: 2, owner: 3 };
const LOGIN_MAX_FAILS = 5;
const LOGIN_WINDOW_MS = 15 * 60 * 1000;

function emptyData() {
  return { users: {}, boards: {}, columns: {}, cards: {}, labels: {}, comments: {}, activity: [] };
}

function hashPassword(password, salt = crypto.randomBytes(16).toString('hex')) {
  const hash = crypto.scryptSync(password, salt, 64).toString('hex');
  return { salt, hash };
}
function verifyPassword(password, salt, hash) {
  const h = crypto.scryptSync(password, salt, 64);
  const expected = Buffer.from(hash, 'hex');
  return expected.length === h.length && crypto.timingSafeEqual(h, expected);
}

const isStr = (v) => typeof v === 'string';
const isDate = (v) => {
  if (!isStr(v) || !/^\d{4}-\d{2}-\d{2}$/.test(v)) return false;
  const d = new Date(v + 'T00:00:00Z');
  return !isNaN(d) && d.toISOString().slice(0, 10) === v;
};
const clamp = (n, lo, hi) => Math.max(lo, Math.min(hi, n));

export function createServer({ dataFile } = {}) {
  let data = emptyData();
  if (dataFile && fs.existsSync(dataFile)) {
    try {
      const raw = fs.readFileSync(dataFile, 'utf8');
      if (raw.trim()) data = { ...emptyData(), ...JSON.parse(raw) };
    } catch {
      data = emptyData();
    }
  }
  const sessions = new Map(); // token -> userId
  const loginFails = new Map(); // username -> [timestamps]
  let lastTs = 0;

  function now() {
    let t = Date.now();
    if (t <= lastTs) t = lastTs + 1;
    lastTs = t;
    return new Date(t).toISOString();
  }
  const newId = () => crypto.randomUUID();

  function save() {
    if (!dataFile) return;
    const dir = path.dirname(path.resolve(dataFile));
    fs.mkdirSync(dir, { recursive: true });
    const tmp = `${dataFile}.${process.pid}.tmp`;
    fs.writeFileSync(tmp, JSON.stringify(data));
    fs.renameSync(tmp, dataFile);
  }

  // ---------- serializers ----------
  const userOut = (u) => ({ id: u.id, username: u.username, displayName: u.displayName });
  const cardOut = (c) => ({
    id: c.id, boardId: c.boardId, columnId: c.columnId, title: c.title, description: c.description,
    position: c.position, assignees: [...c.assignees], labels: [...c.labels], dueDate: c.dueDate,
    createdBy: c.createdBy, createdAt: c.createdAt, updatedAt: c.updatedAt,
  });
  const labelOut = (l) => ({ id: l.id, boardId: l.boardId, name: l.name, color: l.color });
  const memberOut = (m) => ({ userId: m.userId, username: data.users[m.userId]?.username ?? null, role: m.role });
  const columnOut = (col, withCards = true) => {
    const o = { id: col.id, boardId: col.boardId, name: col.name, position: col.position, wipLimit: col.wipLimit };
    if (withCards) o.cards = columnCards(col.id).map(cardOut);
    return o;
  };
  const commentOut = (c) => ({ id: c.id, cardId: c.cardId, authorId: c.authorId, body: c.body, createdAt: c.createdAt });
  const boardOut = (b) => ({
    id: b.id, name: b.name, description: b.description, ownerId: b.ownerId, createdAt: b.createdAt,
    members: b.members.map(memberOut),
    labels: Object.values(data.labels).filter((l) => l.boardId === b.id).map(labelOut),
    columns: boardColumns(b.id).map((c) => columnOut(c)),
  });

  // ---------- helpers ----------
  const boardColumns = (boardId) =>
    Object.values(data.columns).filter((c) => c.boardId === boardId).sort((a, b) => a.position - b.position);
  const columnCards = (colId) =>
    Object.values(data.cards).filter((c) => c.columnId === colId).sort((a, b) => a.position - b.position);
  const renumber = (list) => list.forEach((x, i) => { x.position = i; });

  function activity(boardId, type, actorId, details = {}, cardId) {
    const e = { id: newId(), boardId, type, actorId, at: now(), details };
    if (cardId) e.cardId = cardId;
    data.activity.push(e);
  }

  function roleOf(board, userId) {
    return board.members.find((m) => m.userId === userId)?.role || null;
  }
  function requireRole(board, user, min) {
    const role = roleOf(board, user.id);
    if (!role) throw forbidden('Not a member of this board');
    if (ROLE_RANK[role] < ROLE_RANK[min]) throw forbidden(`Requires ${min} role`);
    return role;
  }
  function getBoard(id, user, min = 'viewer') {
    const b = data.boards[id];
    if (!b) throw notFound('Board not found');
    requireRole(b, user, min);
    return b;
  }
  function getColumn(id, user, min = 'viewer') {
    const c = data.columns[id];
    if (!c) throw notFound('Column not found');
    const b = data.boards[c.boardId];
    if (!b) throw notFound('Column not found');
    requireRole(b, user, min);
    return { col: c, board: b };
  }
  function getCard(id, user, min = 'viewer') {
    const c = data.cards[id];
    if (!c) throw notFound('Card not found');
    const b = data.boards[c.boardId];
    if (!b) throw notFound('Card not found');
    requireRole(b, user, min);
    return { card: c, board: b };
  }

  function deleteCardData(cardId) {
    delete data.cards[cardId];
    for (const [id, cm] of Object.entries(data.comments)) if (cm.cardId === cardId) delete data.comments[id];
  }

  // ---------- validators ----------
  function vName(v, max, field = 'name') {
    if (!isStr(v) || v.trim().length < 1 || v.length > max) throw bad(`${field} must be 1-${max} characters`);
    return v;
  }
  function vOptString(v, field, max = 10000) {
    if (v === undefined || v === null) return '';
    if (!isStr(v) || v.length > max) throw bad(`${field} must be a string`);
    return v;
  }
  function vWip(v) {
    if (v === undefined || v === null) return null;
    if (!Number.isInteger(v) || v < 1) throw bad('wipLimit must be a positive integer or null');
    return v;
  }
  function vPosition(v) {
    if (v === undefined || v === null) return undefined;
    if (!Number.isInteger(v)) throw bad('position must be an integer');
    return v;
  }
  function vDue(v) {
    if (v === undefined || v === null) return null;
    if (!isDate(v)) throw bad('dueDate must be YYYY-MM-DD or null');
    return v;
  }
  function vAssignees(v, board) {
    if (v === undefined || v === null) return [];
    if (!Array.isArray(v) || !v.every(isStr)) throw bad('assignees must be an array of user ids');
    for (const id of v) if (!roleOf(board, id)) throw bad(`assignee ${id} is not a board member`);
    return [...new Set(v)];
  }
  function vLabels(v, board) {
    if (v === undefined || v === null) return [];
    if (!Array.isArray(v) || !v.every(isStr)) throw bad('labels must be an array of label ids');
    for (const id of v) if (data.labels[id]?.boardId !== board.id) throw bad(`label ${id} does not belong to board`);
    return [...new Set(v)];
  }
  function vColor(v) {
    if (!isStr(v) || !/^#[0-9a-fA-F]{6}$/.test(v)) throw bad('color must be #rrggbb');
    return v.toLowerCase();
  }

  // ---------- routes ----------
  const routes = [];
  const route = (method, pattern, handler, { auth = true } = {}) => {
    const keys = [];
    const re = new RegExp('^' + pattern.replace(/:(\w+)/g, (_, k) => { keys.push(k); return '([^/]+)'; }) + '/?$');
    routes.push({ method, re, keys, handler, auth });
  };

  // Auth
  route('POST', '/api/auth/register', ({ body }) => {
    const { username, password, displayName } = body;
    if (!isStr(username) || !/^[a-zA-Z0-9_]{3,32}$/.test(username)) throw bad('username must be 3-32 chars of [a-z0-9_]');
    if (!isStr(password) || password.length < 8) throw bad('password must be at least 8 characters');
    if (displayName !== undefined && displayName !== null && (!isStr(displayName) || displayName.length > 100)) throw bad('displayName must be a string');
    const uname = username.toLowerCase();
    if (Object.values(data.users).some((u) => u.username === uname)) throw conflict('Username already taken');
    const { salt, hash } = hashPassword(password);
    const u = { id: newId(), username: uname, displayName: displayName && displayName.trim() ? displayName : uname, salt, passwordHash: hash, createdAt: now() };
    data.users[u.id] = u;
    save();
    return [201, { user: userOut(u) }];
  }, { auth: false });

  route('POST', '/api/auth/login', ({ body }) => {
    const { username, password } = body;
    if (!isStr(username) || !isStr(password)) throw bad('username and password required');
    const uname = username.toLowerCase();
    const t = Date.now();
    const fails = (loginFails.get(uname) || []).filter((x) => t - x < LOGIN_WINDOW_MS);
    loginFails.set(uname, fails);
    if (fails.length >= LOGIN_MAX_FAILS) throw new HttpError(429, 'rate_limited', 'Too many failed login attempts');
    const u = Object.values(data.users).find((x) => x.username === uname);
    if (!u || !verifyPassword(password, u.salt, u.passwordHash)) {
      fails.push(t);
      throw new HttpError(401, 'unauthenticated', 'Invalid credentials');
    }
    loginFails.delete(uname);
    const token = crypto.randomBytes(32).toString('hex');
    sessions.set(token, u.id);
    return [200, { token, user: userOut(u) }];
  }, { auth: false });

  route('POST', '/api/auth/logout', ({ token }) => {
    sessions.delete(token);
    return [204];
  });
  route('GET', '/api/auth/me', ({ user }) => [200, { user: userOut(user) }]);

  // Boards
  route('POST', '/api/boards', ({ user, body }) => {
    const name = vName(body.name, 100);
    const description = vOptString(body.description, 'description');
    let cols = body.columns;
    if (cols === undefined || cols === null) cols = ['To Do', 'In Progress', 'Done'];
    if (!Array.isArray(cols)) throw bad('columns must be an array of names');
    cols.forEach((c) => vName(c, 100, 'column name'));
    const b = { id: newId(), name, description, ownerId: user.id, createdAt: now(), members: [{ userId: user.id, role: 'owner' }] };
    data.boards[b.id] = b;
    activity(b.id, 'board.created', user.id, { name });
    cols.forEach((cn, i) => {
      const col = { id: newId(), boardId: b.id, name: cn, position: i, wipLimit: null };
      data.columns[col.id] = col;
      activity(b.id, 'column.created', user.id, { columnId: col.id, name: cn });
    });
    save();
    return [201, boardOut(b)];
  });

  route('GET', '/api/boards', ({ user }) => [200, Object.values(data.boards)
    .filter((b) => roleOf(b, user.id))
    .sort((a, b) => a.createdAt.localeCompare(b.createdAt))
    .map((b) => ({ id: b.id, name: b.name, role: roleOf(b, user.id) }))]);

  route('GET', '/api/boards/:id', ({ user, params }) => [200, boardOut(getBoard(params.id, user))]);

  route('PATCH', '/api/boards/:id', ({ user, params, body }) => {
    const b = getBoard(params.id, user, 'owner');
    const changes = {};
    if (body.name !== undefined) changes.name = vName(body.name, 100);
    if (body.description !== undefined) changes.description = vOptString(body.description, 'description');
    Object.assign(b, changes);
    activity(b.id, 'board.updated', user.id, { changes: Object.keys(changes) });
    save();
    return [200, boardOut(b)];
  });

  route('DELETE', '/api/boards/:id', ({ user, params }) => {
    const b = getBoard(params.id, user, 'owner');
    for (const c of Object.values(data.cards)) if (c.boardId === b.id) deleteCardData(c.id);
    for (const c of Object.values(data.columns)) if (c.boardId === b.id) delete data.columns[c.id];
    for (const l of Object.values(data.labels)) if (l.boardId === b.id) delete data.labels[l.id];
    data.activity = data.activity.filter((a) => a.boardId !== b.id);
    delete data.boards[b.id];
    save();
    return [204];
  });

  // Members
  route('GET', '/api/boards/:id/members', ({ user, params }) => [200, getBoard(params.id, user).members.map(memberOut)]);

  route('POST', '/api/boards/:id/members', ({ user, params, body }) => {
    const b = getBoard(params.id, user, 'owner');
    if (!isStr(body.username)) throw bad('username required');
    if (body.role !== 'editor' && body.role !== 'viewer') throw bad('role must be editor or viewer');
    const target = Object.values(data.users).find((u) => u.username === body.username.toLowerCase());
    if (!target) throw notFound('User not found');
    if (roleOf(b, target.id)) throw conflict('User is already a member');
    const m = { userId: target.id, role: body.role };
    b.members.push(m);
    activity(b.id, 'member.added', user.id, { userId: target.id, role: m.role });
    save();
    return [201, memberOut(m)];
  });

  route('PATCH', '/api/boards/:id/members/:userId', ({ user, params, body }) => {
    const b = getBoard(params.id, user, 'owner');
    const m = b.members.find((x) => x.userId === params.userId);
    if (!m) throw notFound('Member not found');
    if (body.role !== 'editor' && body.role !== 'viewer') throw bad('role must be editor or viewer');
    if (m.role === 'owner') throw bad("Cannot change the owner's role");
    const from = m.role;
    m.role = body.role;
    activity(b.id, 'member.updated', user.id, { userId: m.userId, from, to: m.role });
    save();
    return [200, memberOut(m)];
  });

  route('DELETE', '/api/boards/:id/members/:userId', ({ user, params }) => {
    const b = data.boards[params.id];
    if (!b) throw notFound('Board not found');
    const myRole = roleOf(b, user.id);
    if (!myRole) throw forbidden('Not a member of this board');
    const self = params.userId === user.id;
    if (myRole !== 'owner' && !self) throw forbidden('Only the owner can remove members');
    const m = b.members.find((x) => x.userId === params.userId);
    if (!m) throw notFound('Member not found');
    if (m.role === 'owner') throw bad('Cannot remove the board owner');
    b.members = b.members.filter((x) => x !== m);
    for (const c of Object.values(data.cards)) {
      if (c.boardId === b.id) c.assignees = c.assignees.filter((a) => a !== m.userId);
    }
    activity(b.id, 'member.removed', user.id, { userId: m.userId });
    save();
    return [204];
  });

  // Columns
  route('GET', '/api/boards/:id/columns', ({ user, params }) => [200, boardColumns(getBoard(params.id, user).id).map((c) => columnOut(c))]);

  route('POST', '/api/boards/:id/columns', ({ user, params, body }) => {
    const b = getBoard(params.id, user, 'editor');
    const name = vName(body.name, 100);
    const wipLimit = vWip(body.wipLimit);
    const col = { id: newId(), boardId: b.id, name, position: boardColumns(b.id).length, wipLimit };
    data.columns[col.id] = col;
    activity(b.id, 'column.created', user.id, { columnId: col.id, name });
    save();
    return [201, columnOut(col)];
  });

  route('GET', '/api/columns/:id', ({ user, params }) => [200, columnOut(getColumn(params.id, user).col)]);

  route('PATCH', '/api/columns/:id', ({ user, params, body }) => {
    const { col, board } = getColumn(params.id, user, 'editor');
    const name = body.name !== undefined ? vName(body.name, 100) : undefined;
    const wipLimit = body.wipLimit !== undefined ? vWip(body.wipLimit) : undefined;
    const position = vPosition(body.position);
    if (name !== undefined) col.name = name;
    if (body.wipLimit !== undefined) col.wipLimit = wipLimit;
    if (position !== undefined) {
      const list = boardColumns(board.id).filter((c) => c.id !== col.id);
      list.splice(clamp(position, 0, list.length), 0, col);
      renumber(list);
    }
    activity(board.id, 'column.updated', user.id, { columnId: col.id });
    save();
    return [200, columnOut(col)];
  });

  route('DELETE', '/api/columns/:id', ({ user, params, query }) => {
    const { col, board } = getColumn(params.id, user, 'editor');
    const cards = columnCards(col.id);
    if (cards.length && query.get('force') !== 'true') throw conflict('Column still has cards');
    cards.forEach((c) => deleteCardData(c.id));
    delete data.columns[col.id];
    renumber(boardColumns(board.id));
    activity(board.id, 'column.deleted', user.id, { columnId: col.id, name: col.name, cardsDeleted: cards.length });
    save();
    return [204];
  });

  // Cards
  route('POST', '/api/columns/:id/cards', ({ user, params, body }) => {
    const { col, board } = getColumn(params.id, user, 'editor');
    const title = vName(body.title, 200, 'title');
    const description = vOptString(body.description, 'description');
    const assignees = vAssignees(body.assignees, board);
    const labels = vLabels(body.labels, board);
    const dueDate = vDue(body.dueDate);
    const position = vPosition(body.position);
    const list = columnCards(col.id);
    if (col.wipLimit != null && list.length >= col.wipLimit) throw conflict('Column WIP limit reached', 'wip_limit');
    const ts = now();
    const card = { id: newId(), boardId: board.id, columnId: col.id, title, description, position: 0, assignees, labels, dueDate, createdBy: user.id, createdAt: ts, updatedAt: ts };
    data.cards[card.id] = card;
    list.splice(position === undefined ? list.length : clamp(position, 0, list.length), 0, card);
    renumber(list);
    activity(board.id, 'card.created', user.id, { columnId: col.id, title }, card.id);
    save();
    return [201, cardOut(card)];
  });

  route('GET', '/api/cards/:id', ({ user, params }) => [200, cardOut(getCard(params.id, user).card)]);

  route('PATCH', '/api/cards/:id', ({ user, params, body }) => {
    const { card, board } = getCard(params.id, user, 'editor');
    const ch = {};
    if (body.title !== undefined) ch.title = vName(body.title, 200, 'title');
    if (body.description !== undefined) ch.description = vOptString(body.description, 'description');
    if (body.assignees !== undefined) ch.assignees = vAssignees(body.assignees, board);
    if (body.labels !== undefined) ch.labels = vLabels(body.labels, board);
    if (body.dueDate !== undefined) ch.dueDate = vDue(body.dueDate);
    Object.assign(card, ch);
    card.updatedAt = now();
    activity(board.id, 'card.updated', user.id, { fields: Object.keys(ch) }, card.id);
    save();
    return [200, cardOut(card)];
  });

  route('DELETE', '/api/cards/:id', ({ user, params }) => {
    const { card, board } = getCard(params.id, user, 'editor');
    deleteCardData(card.id);
    renumber(columnCards(card.columnId));
    activity(board.id, 'card.deleted', user.id, { columnId: card.columnId, title: card.title }, card.id);
    save();
    return [204];
  });

  route('POST', '/api/cards/:id/move', ({ user, params, body }) => {
    const { card, board } = getCard(params.id, user, 'editor');
    if (!isStr(body.columnId)) throw bad('columnId required');
    const target = data.columns[body.columnId];
    if (!target || target.boardId !== board.id) throw bad('Target column must be on the same board');
    const position = vPosition(body.position);
    const fromColumnId = card.columnId;
    const fromPosition = card.position;
    const targetList = columnCards(target.id).filter((c) => c.id !== card.id);
    if (target.id !== fromColumnId && target.wipLimit != null && targetList.length >= target.wipLimit) {
      throw conflict('Column WIP limit reached', 'wip_limit');
    }
    targetList.splice(position === undefined ? targetList.length : clamp(position, 0, targetList.length), 0, card);
    card.columnId = target.id;
    renumber(targetList);
    if (fromColumnId !== target.id) renumber(columnCards(fromColumnId));
    card.updatedAt = now();
    activity(board.id, 'card.moved', user.id, { fromColumnId, toColumnId: target.id, fromPosition, toPosition: card.position }, card.id);
    save();
    return [200, cardOut(card)];
  });

  // Labels
  route('GET', '/api/boards/:id/labels', ({ user, params }) => {
    const b = getBoard(params.id, user);
    return [200, Object.values(data.labels).filter((l) => l.boardId === b.id).map(labelOut)];
  });

  route('POST', '/api/boards/:id/labels', ({ user, params, body }) => {
    const b = getBoard(params.id, user, 'editor');
    const name = vName(body.name, 50);
    const color = vColor(body.color);
    if (Object.values(data.labels).some((l) => l.boardId === b.id && l.name.toLowerCase() === name.toLowerCase())) throw conflict('Label name already exists');
    const l = { id: newId(), boardId: b.id, name, color };
    data.labels[l.id] = l;
    activity(b.id, 'label.created', user.id, { labelId: l.id, name });
    save();
    return [201, labelOut(l)];
  });

  function getLabel(id, user, min) {
    const l = data.labels[id];
    if (!l || !data.boards[l.boardId]) throw notFound('Label not found');
    const board = getBoard(l.boardId, user, min);
    return { label: l, board };
  }

  route('PATCH', '/api/labels/:id', ({ user, params, body }) => {
    const { label, board } = getLabel(params.id, user, 'editor');
    const name = body.name !== undefined ? vName(body.name, 50) : undefined;
    const color = body.color !== undefined ? vColor(body.color) : undefined;
    if (name !== undefined && Object.values(data.labels).some((l) => l.boardId === board.id && l.id !== label.id && l.name.toLowerCase() === name.toLowerCase())) throw conflict('Label name already exists');
    if (name !== undefined) label.name = name;
    if (color !== undefined) label.color = color;
    save();
    return [200, labelOut(label)];
  });

  route('DELETE', '/api/labels/:id', ({ user, params }) => {
    const { label, board } = getLabel(params.id, user, 'editor');
    delete data.labels[label.id];
    for (const c of Object.values(data.cards)) {
      if (c.labels.includes(label.id)) c.labels = c.labels.filter((x) => x !== label.id);
    }
    activity(board.id, 'label.deleted', user.id, { labelId: label.id, name: label.name });
    save();
    return [204];
  });

  // Comments
  route('POST', '/api/cards/:id/comments', ({ user, params, body }) => {
    const { card, board } = getCard(params.id, user, 'editor');
    const text = body.body;
    if (!isStr(text) || text.trim().length < 1 || text.length > 5000) throw bad('body must be 1-5000 characters');
    const cm = { id: newId(), cardId: card.id, boardId: board.id, authorId: user.id, body: text, createdAt: now() };
    data.comments[cm.id] = cm;
    activity(board.id, 'comment.added', user.id, { commentId: cm.id }, card.id);
    save();
    return [201, commentOut(cm)];
  });

  route('GET', '/api/cards/:id/comments', ({ user, params }) => {
    const { card } = getCard(params.id, user);
    return [200, Object.values(data.comments).filter((c) => c.cardId === card.id)
      .sort((a, b) => a.createdAt.localeCompare(b.createdAt)).map(commentOut)];
  });

  route('DELETE', '/api/comments/:id', ({ user, params }) => {
    const cm = data.comments[params.id];
    if (!cm) throw notFound('Comment not found');
    const card = data.cards[cm.cardId];
    const board = card && data.boards[card.boardId];
    if (!board) throw notFound('Comment not found');
    const role = roleOf(board, user.id);
    if (!role) throw forbidden('Not a member of this board');
    if (cm.authorId !== user.id && role !== 'owner') throw forbidden('Only the author or board owner can delete');
    delete data.comments[cm.id];
    activity(board.id, 'comment.deleted', user.id, { commentId: cm.id }, card.id);
    save();
    return [204];
  });

  // Search
  route('GET', '/api/boards/:id/cards', ({ user, params, query }) => {
    const b = getBoard(params.id, user);
    const q = query.get('q');
    const assignee = query.get('assignee');
    const label = query.get('label');
    const column = query.get('column');
    const dueBefore = query.get('due_before');
    if (dueBefore && !isDate(dueBefore)) throw bad('due_before must be YYYY-MM-DD');
    const ql = q ? q.toLowerCase() : '';
    const out = [];
    for (const col of boardColumns(b.id)) {
      if (column && col.id !== column) continue;
      for (const c of columnCards(col.id)) {
        if (ql && !c.title.toLowerCase().includes(ql) && !(c.description || '').toLowerCase().includes(ql)) continue;
        if (assignee && !c.assignees.includes(assignee)) continue;
        if (label && !c.labels.includes(label)) continue;
        if (dueBefore && (!c.dueDate || !(c.dueDate < dueBefore))) continue;
        out.push(cardOut(c));
      }
    }
    return [200, out];
  });

  // Activity
  route('GET', '/api/boards/:id/activity', ({ user, params, query }) => {
    const b = getBoard(params.id, user);
    let limit = 50;
    const raw = query.get('limit');
    if (raw !== null && raw !== '') {
      limit = Number(raw);
      if (!Number.isInteger(limit) || limit < 0) throw bad('limit must be a non-negative integer');
    }
    const entries = [];
    for (let i = data.activity.length - 1; i >= 0 && entries.length < limit; i--) {
      if (data.activity[i].boardId === b.id) entries.push(data.activity[i]);
    }
    return [200, entries];
  });

  // ---------- HTTP plumbing ----------
  function send(res, status, body, headers = {}) {
    if (status === 204 || body === undefined) {
      res.writeHead(status, headers);
      res.end();
      return;
    }
    const payload = JSON.stringify(body);
    res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Content-Length': Buffer.byteLength(payload), ...headers });
    res.end(payload);
  }

  function readBody(req) {
    return new Promise((resolve, reject) => {
      const chunks = [];
      let size = 0;
      req.on('data', (c) => {
        size += c.length;
        if (size > 5 * 1024 * 1024) { reject(new HttpError(413, 'payload_too_large', 'Body too large')); req.destroy(); return; }
        chunks.push(c);
      });
      req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
      req.on('error', reject);
    });
  }

  function serveStatic(res, file, type) {
    try {
      const content = fs.readFileSync(path.join(__dirname, 'public', file));
      res.writeHead(200, { 'Content-Type': type, 'Content-Length': content.length });
      res.end(content);
    } catch {
      send(res, 404, { error: 'not_found', message: 'Not found' });
    }
  }

  const STATIC_TYPES = { '.js': 'text/javascript; charset=utf-8', '.css': 'text/css; charset=utf-8', '.html': 'text/html; charset=utf-8' };

  async function handle(req, res) {
    const url = new URL(req.url, 'http://localhost');
    const pathname = url.pathname;
    const method = req.method.toUpperCase();

    if ((method === 'GET' || method === 'HEAD') && (pathname === '/' || pathname === '/index.html')) {
      return serveStatic(res, 'index.html', 'text/html; charset=utf-8');
    }
    if ((method === 'GET' || method === 'HEAD') && pathname.startsWith('/static/')) {
      const name = path.basename(pathname);
      const ext = path.extname(name);
      if (!STATIC_TYPES[ext] || name.startsWith('.')) return send(res, 404, { error: 'not_found', message: 'Not found' });
      return serveStatic(res, name, STATIC_TYPES[ext]);
    }

    let match = null;
    for (const r of routes) {
      if (r.method !== method) continue;
      const m = r.re.exec(pathname);
      if (m) {
        const params = {};
        r.keys.forEach((k, i) => { params[k] = decodeURIComponent(m[i + 1]); });
        match = { r, params };
        break;
      }
    }
    if (!match) throw notFound('Route not found');

    let user = null;
    let token = null;
    if (match.r.auth) {
      const h = req.headers.authorization || '';
      const m = /^Bearer\s+(\S+)$/i.exec(h);
      token = m ? m[1] : null;
      const uid = token ? sessions.get(token) : null;
      user = uid ? data.users[uid] : null;
      if (!user) throw new HttpError(401, 'unauthenticated', 'Authentication required');
    }

    let body = {};
    if (method === 'POST' || method === 'PATCH' || method === 'PUT') {
      const raw = await readBody(req);
      if (raw.trim()) {
        try { body = JSON.parse(raw); } catch { throw bad('Invalid JSON'); }
        if (body === null || typeof body !== 'object' || Array.isArray(body)) throw bad('JSON body must be an object');
      }
    }

    const [status, out] = await match.r.handler({ req, user, token, params: match.params, query: url.searchParams, body });
    send(res, status, out);
  }

  const server = http.createServer((req, res) => {
    handle(req, res).catch((err) => {
      if (err instanceof HttpError) {
        send(res, err.status, { error: err.code, message: err.message });
      } else {
        console.error(err);
        send(res, 500, { error: 'internal', message: 'Internal server error' });
      }
    });
  });
  return server;
}

